const VERSION = "__VERSION__";
const CACHE = `outbreakpulse-${VERSION}`;
const PRECACHE = __PRECACHE__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("outbreakpulse-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

function normalize(url) {
  const u = new URL(url);
  let path = u.pathname;
  if (!path.endsWith("/") && !path.split("/").pop().includes(".")) path += "/";
  return path;
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  // Firebase, Google APIs and other origins are never intercepted.
  if (url.origin !== self.location.origin) return;

  if (request.mode === "navigate") {
    // Network first for pages so updates arrive quickly; cached shell when offline.
    event.respondWith(
      fetch(request).catch(async () => {
        const cache = await caches.open(CACHE);
        return (
          (await cache.match(normalize(request.url), { ignoreSearch: true })) ||
          (await cache.match("/", { ignoreSearch: true })) ||
          Response.error()
        );
      }),
    );
    return;
  }

  // Static assets are content-hashed: cache first.
  event.respondWith(
    caches.match(request, { ignoreSearch: url.pathname.endsWith(".txt") }).then((hit) => hit || fetch(request)),
  );
});
